mapper.update:
UPDATE
    l_user


        status = #{status},

    edit_time = #{editTime}

WHERE
    id = #{id}

mapper.select:
SELECT lu.*, visit_ip AS visitIp, visit_time AS visitTime FROM l_user lu LEFT JOIN ( SELECT user_id, visit_ip, visit_time, ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY visit_time DESC) AS rn FROM l_user_visit_record) luvr ON lu.id = luvr.user_id AND luvr.rn = 1
AND lu.name LIKE CONCAT('%', #{user.name}, '%')
AND lu.status = #{user.status}
ORDER BY lu.id DESC LIMIT #{startNum}, #{size}

SELECT COUNT(id) FROM l_user
AND name LIKE CONCAT('%', #{name}, '%')
AND status = #{status}
AND add_time >= #{addTime}
